with recursive TagHierarchy as (
  select Id, TagName, Count, ExcerptPostId, WikiPostId, cast(TagName as varchar(1000)) as FullPath, 1 as Level
    from Tags
   where ParentId is null
  union all
  select c.Id, c.TagName, c.Count, c.ExcerptPostId, c.WikiPostId,
         concat(th.FullPath, '>|<', c.TagName),
         th.Level+1
    from Tags c
         join TagHierarchy th on c.ParentId = th.Id
),
